toolScript:
const letters = ['E', 'F', 'P', 'T', 'O', 'Z'];
        const results = { left: null, right: null };
        let currentEye = 'right';
        let currentLetter = 'E';

        function selectEye(eye) {
            document.querySelectorAll('.eye-indicator').forEach(e => e.classList.remove('active'));
            document.getElementById('eye-' + eye).classList.add('active');
            currentEye = eye;
            generateNewLetter();
        }

        function generateNewLetter() {
            currentLetter = letters[Math.floor(Math.random() * letters.length)];
            document.getElementById('green-letter').textContent = currentLetter;
            document.getElementById('red-letter').textContent = currentLetter;
        }

        function selectColor(color) {
            results[currentEye] = color;
            updateResultsPanel();
            generateNewLetter();
            document.getElementById('results-panel').classList.remove('hidden');
        }

        function updateResultsPanel() {
            const resultLeft = document.getElementById('result-left');
            const resultRight = document.getElementById('result-right');
            const resultLeftDetail = document.getElementById('result-left-detail');
            const resultRightDetail = document.getElementById('result-right-detail');
            const recommendation = document.getElementById('recommendation');

            if (results.left) {
                if (results.left === 'green') {
                    resultLeft.textContent = 'Slight Myopia';
                    resultLeftDetail.textContent = 'Green clearer  to  Over-focused';
                    resultLeft.classList.add('text-green-600');
                } else if (results.left === 'red') {
                    resultLeft.textContent = 'Slight Hyperopia';
                    resultLeftDetail.textContent = 'Red clearer  to  Under-focused';
                    resultLeft.classList.add('text-red-600');
                } else {
                    resultLeft.textContent = 'Balanced';
                    resultLeftDetail.textContent = 'Colors equal  to  Well-focused';
                    resultLeft.classList.add('text-teal-600');
                }
            }

            if (results.right) {
                if (results.right === 'green') {
                    resultRight.textContent = 'Slight Myopia';
                    resultRightDetail.textContent = 'Green clearer  to  Over-focused';
                    resultRight.classList.add('text-green-600');
                } else if (results.right === 'red') {
                    resultRight.textContent = 'Slight Hyperopia';
                    resultRightDetail.textContent = 'Red clearer  to  Under-focused';
                    resultRight.classList.add('text-red-600');
                } else {
                    resultRight.textContent = 'Balanced';
                    resultRightDetail.textContent = 'Colors equal  to  Well-focused';
                    resultRight.classList.add('text-teal-600');
                }
            }

            if (results.left && results.right) {
                if (results.left === results.right) {
                    recommendation.textContent = 'Both eyes show similar tendencies. Your prescription balance appears consistent.';
                } else {
                    recommendation.textContent = 'Eyes show different balance patterns. Consider an eye exam to check for anisometropia.';
                }
            }
        }

        function resetTest() {
            results.left = null;
            results.right = null;
            document.getElementById('result-left').textContent = 'Not Tested';
            document.getElementById('result-right').textContent = 'Not Tested';
            document.getElementById('result-left-detail').textContent = '--';
            document.getElementById('result-right-detail').textContent = '--';
            document.getElementById('recommendation').textContent = 'Complete testing for both eyes to get recommendations.';
            generateNewLetter();
        }
